/**
 * Converts WGS84 (lat/lon) to Dutch RD New coordinates (X, Y).
 * Based on the official Dutch transformation formulas from NSGI.
 */
function wgs84ToRd(lat, lon) {
    // Reference point Amersfoort
    const lat0 = 52.15517440;
    const lon0 = 5.38720621;
    const x0 = 155000.00;
    const y0 = 463000.00;

    const dLat = 0.36 * (lat - lat0);
    const dLon = 0.36 * (lon - lon0);

    const Kp = [0, 2, 0, 2, 0, 2, 1, 4, 2, 4, 1];
    const Kq = [1, 0, 2, 1, 3, 2, 0, 0, 3, 1, 1];
    const Kpq = [190094.945, -11832.228, -114.221, -32.391, -0.705, -2.340, -0.608, -0.008, 0.148, 0.022, -0.022];

    const Lp = [1, 1, 1, 3, 1, 3, 0, 3, 1, 0, 2, 5];
    const Lq = [0, 1, 2, 0, 3, 1, 1, 2, 4, 2, 0, 0];
    const Lpq = [309056.544, 3638.893, 73.077, -157.984, 59.788, 0.433, -6.439, -0.032, 0.092, -0.054, 0.054, 0.022];

    let x = 0;
    for (let i = 0; i < Kpq.length; i++) {
        x += Kpq[i] * Math.pow(dLat, Kp[i]) * Math.pow(dLon, Kq[i]);
    }

    let y = 0;
    for (let i = 0; i < Lpq.length; i++) {
        y += Lpq[i] * Math.pow(dLat, Lp[i]) * Math.pow(dLon, Lq[i]);
    }

    return { x: x0 + x, y: y0 + y };
}
// END EXTRA CODE

/**
 * Converts WGS84 latitude/longitude to Dutch RD New (Rijksdriehoek) X and Y coordinates. Returns a string in the format 'X,Y'.
 * @param {Big} lon - Longitude in WGS84 (e.g. 4.9)
 * @param {Big} lat - Latitude in WGS84 (e.g. 52.3)
 * @returns {Promise.<string>}
 */
export async function JSA_WGS84_NaarRDNew(lon, lat) {
	// BEGIN USER CODE
    if (lat === undefined || lon === undefined) return "0,0";
    const latNum = parseFloat(lat.toString());
    const lonNum = parseFloat(lon.toString());
    const rd = wgs84ToRd(latNum, lonNum);
    return Math.round(rd.x) + "," + Math.round(rd.y);
	// END USER CODE
}
